<?php
session_start();require_once "config/conexao.php";
if($_SERVER["REQUEST_METHOD"]==="POST"){$id=(int)($_POST["id"]??0);$nome=trim($_POST["nome"]??"");$documento=trim($_POST["documento"]??"");$telefone=trim($_POST["telefone"]??"");$veiculo=trim($_POST["veiculo"]??"");$placa=strtoupper(trim($_POST["placa"]??""));
if($nome!==""){if($id){$st=$conn->prepare("UPDATE transportadores SET nome=?,documento=?,telefone=?,veiculo=?,placa=? WHERE id=?");$st->bind_param("sssssi",$nome,$documento,$telefone,$veiculo,$placa,$id);}else{$st=$conn->prepare("INSERT INTO transportadores(nome,documento,telefone,veiculo,placa) VALUES(?,?,?,?,?)");$st->bind_param("sssss",$nome,$documento,$telefone,$veiculo,$placa);}$st->execute();$_SESSION["mensagem"]="Transportador salvo com sucesso.";}else $_SESSION["mensagem"]="Informe o nome do transportador.";header("Location: transportadores.php");exit;}
if(isset($_GET["excluir"])){$id=(int)$_GET["excluir"];$st=$conn->prepare("DELETE FROM transportadores WHERE id=?");$st->bind_param("i",$id);$st->execute();$_SESSION["mensagem"]="Transportador excluído, se não estiver vinculado a frete.";header("Location: transportadores.php");exit;}
$editar=null;if(isset($_GET["editar"])){$id=(int)$_GET["editar"];$st=$conn->prepare("SELECT * FROM transportadores WHERE id=?");$st->bind_param("i",$id);$st->execute();$editar=$st->get_result()->fetch_assoc();}
$lista=$conn->query("SELECT * FROM transportadores ORDER BY nome");$titulo="Transportadores";include "includes/cabecalho.php";?>
<div class="container py-4"><h1 class="h3">Transportadores</h1><p class="text-muted">Cadastre quem realizará o transporte.</p>
<div class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5"><?= $editar?"Editar transportador":"Novo transportador" ?></h2><form method="post" class="row g-3"><input type="hidden" name="id" value="<?= (int)($editar["id"]??0) ?>"><div class="col-md-6"><label class="form-label">Nome *</label><input name="nome" class="form-control" required value="<?= htmlspecialchars($editar["nome"]??"") ?>"></div><div class="col-md-3"><label class="form-label">CPF/CNPJ</label><input name="documento" class="form-control" value="<?= htmlspecialchars($editar["documento"]??"") ?>"></div><div class="col-md-3"><label class="form-label">Telefone</label><input name="telefone" class="form-control" value="<?= htmlspecialchars($editar["telefone"]??"") ?>"></div><div class="col-md-6"><label class="form-label">Veículo</label><input name="veiculo" class="form-control" value="<?= htmlspecialchars($editar["veiculo"]??"") ?>"></div><div class="col-md-3"><label class="form-label">Placa</label><input name="placa" class="form-control" value="<?= htmlspecialchars($editar["placa"]??"") ?>"></div><div class="col-12"><button class="btn btn-primary">Salvar transportador</button><?php if($editar): ?> <a class="btn btn-outline-secondary" href="transportadores.php">Cancelar</a><?php endif; ?></div></form></div></div>
<div class="card border-0 shadow-sm"><div class="card-body"><h2 class="h5">Transportadores cadastrados</h2><div class="table-responsive"><table class="table"><thead><tr><th>Nome</th><th>Documento</th><th>Telefone</th><th>Veículo</th><th>Placa</th><th>Ações</th></tr></thead><tbody><?php while($t=$lista->fetch_assoc()): ?><tr><td><?= htmlspecialchars($t["nome"]) ?></td><td><?= htmlspecialchars($t["documento"]) ?></td><td><?= htmlspecialchars($t["telefone"]) ?></td><td><?= htmlspecialchars($t["veiculo"]) ?></td><td><?= htmlspecialchars($t["placa"]) ?></td><td><a href="?editar=<?= $t["id"] ?>">Editar</a> · <a onclick="return confirm('Excluir este transportador?')" href="?excluir=<?= $t["id"] ?>">Excluir</a></td></tr><?php endwhile; ?></tbody></table></div></div></div></div><?php include "includes/rodape.php";?>